script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	console.log(api.data.playbook_custom_layout.selectedItem.playbookContextId, event.payload.value[0]);
	return {
		playbookContextId: api.data.playbook_custom_layout.selectedItem.playbookContextId,
		stageContextId: event.payload.value[0]
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			selectedStage: event.payload.value[0]
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			selectedActivity: event.payload.activityContextId
		}
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (!api.data.playbook_custom_layout.compactMode) return "both";
  return (api.data.playbook_custom_layout.selectedItem || {}).stageContextId ? "right" : "left";
}
